    epsilon = float(parameters["epsilon"])

    A_ratings = np.array(state[0])
    B_ratings = np.array(state[1])

    max_A = np.max(A_ratings)
    max_B = np.max(B_ratings)

    if max_A > max_B:
        p_A_max = 1.0
    elif max_B > max_A:
        p_A_max = 0.0
    else:
        p_A_max = 0.5

    p_A = (1.0 - epsilon) * 0.5 + epsilon * p_A_max

    return np.array([p_A, 1.0 - p_A])

